const preferences: Record<string, boolean> = {
  default_user: false,
};

export function getNotificationPreference(userId: string = "default_user"): boolean {
  return preferences[userId] ?? false;
}

export function toggleNotificationPreference(userId: string = "default_user"): boolean {
  const current = preferences[userId] ?? false;
  const next = !current;
  preferences[userId] = next;
  return next;
}

