import { getNotificationPreference } from "@/lib/notifications";
import { toggleNotifications } from "./actions";

export default async function Home() {
  const enabled = getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {enabled ? "on" : "off"}.</p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? "off" : "on"}
        </button>
      </form>
    </main>
  );
}

